import { observer } from 'mobx-react-lite';
import React, { useContext } from 'react'
import { Button, Container } from 'react-bootstrap';
import { Context } from '..';

const RemoveType = () =>{
    const {dish} = useContext(Context)

    return(
        <Container>
            <Button
                variant='outline-danger'
            >
                Видалити тип
            </Button>

            <Button
                variant='outline-danger'
            >
                Змінити тип
            </Button>
        </Container>
    );
};

export default RemoveType;
